def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    # Each separate four-connected T is a three-cell horizontal bar and a centered stem.
    for r in range(h):
        for c in range(w - 2):
            if grid[r][c:c + 3] != [2, 2, 2]:
                continue
            if r > 0 and grid[r - 1][c + 1] == 2:
                cells = frozenset([(r, c), (r, c + 1), (r, c + 2), (r - 1, c + 1)])
                if cells not in seen:
                    up += 1
                    seen.add(cells)
            if r + 1 < h and grid[r + 1][c + 1] == 2:
                cells = frozenset([(r, c), (r, c + 1), (r, c + 2), (r + 1, c + 1)])
                if cells not in seen:
                    down += 1
                    seen.add(cells)
    out = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (2, 0), (0, 2), (2, 2))
    # Stem above the bar -> 3; stem below -> 1.
    for i in range(min(up, 4)):
        r, c = slots[i]
        out[r][c] = 3
    for i in range(min(down, 4)):
        r, c = slots[i]
        out[r][c + 3] = 1
    return out
